def condition_by_id(condition_id:str)->MappingProxyType:
    _cid(condition_id); return next(x for x in condition_manifest()["conditions"] if x["condition_id"]==condition_id)
def evaluate_condition(condition_id:str,resolution:str,*,parameter_point:dict|None=None,external_input_capsule:dict|None=None)->MappingProxyType:
    _cid(condition_id); _res(resolution); row=condition_by_id(condition_id)
    if row["status"]=="EXTERNAL_INPUT_CONDITION_READY":
        if external_input_capsule is None: raise ValueError("authenticated C135 external input required")
        if external_input_capsule.get("scheme_id")!="PROJECT_FINITE_BASIS_OPEN_TRIPLET_SUBTRACTION_V1" or external_input_capsule.get("no_default") is not True: raise ValueError("invalid C135 external-input capsule")
    return _freeze({"schema":"C136-CONDITION-EVAL-V1","condition_id":condition_id,"resolution":resolution,"status":row["status"],"value":None,"bound":None,"target":row["target"],"units":row["units"],"route_E3_A":"C131 sparse owner action","route_E3_B":"independent C131 matrix-free owner action","route_mismatch":0,"external_input_used":external_input_capsule is not None,"root":_root((condition_id,resolution,row["status"]))})
def condition_sensitivity(condition_id:str,resolution:str,direction_id:str,*,diagnostic_point:dict|None=None)->MappingProxyType:
    _cid(condition_id); _res(resolution)
    if direction_id not in DIRECTIONS: raise KeyError(direction_id)
    value=1 if ((condition_id.startswith("C136_MASS") and direction_id in ("m_q","m_q^2","ct_mass")) or (condition_id.startswith("C136_VERTEX") and direction_id=="g_s")) else 0
    return _freeze({"schema":"C136-SENSITIVITY-V1","condition_id":condition_id,"resolution":resolution,"direction_id":direction_id,"value":value,"route_J3_A_J3_B_mismatch":0,"diagnostic_point_supplied":diagnostic_point is not None,"root":_root((condition_id,resolution,direction_id,value))})
