def counterterm_condition_crosswalk()->MappingProxyType:
    rows=[]
    for x in COUNTERTERMS:
        block=next(b for b in counterterm_primitive_manifest()["blocks"] if b["direction_id"]==x)
        rows.append({"direction_id":x,"primitive_support":block["primitive_block_id"],"candidate_conditions":("C136_MASS_K9",) if x=="ct_mass" else tuple(),"selected":("C136_MASS_K9",) if x=="ct_mass" else tuple(),"sensitivity":1 if x=="ct_mass" else 0,"status":"CONDITIONAL_ON_EXTERNAL_INPUT" if x=="ct_mass" else "NO_ADMISSIBLE_CONDITION" if x in ("ct_gluon_mass","ct_sector") else "TRUNCATION_DIRECTION_ONLY"})
    rows=tuple(rows)
    return _freeze({"schema":"C136-COUNTERTERM-CROSSWALK-V1","directions":rows,"count":6,"root":_root(rows)})
